/** Готовый ответ GET /api/public/grammar: пройденные карточки грамматики. */
export const STUDY_GRAMMAR = "{\"count\": 31, \"grammar\": [\n{\"id\":\"iyo\",\"ko\":\"이에요 / 예요\",\"ru\":\"быть, являться («это…», «я…»)\",\"section\":\"Быть и отрицание\",\"lesson\":\"Урок 1\",\"about\":\"вежливая связка в конце предложения\",\"blocks\":[{\"type\":\"text\",\"text\":\"Вежливое окончание «это… / я…» — базовая связка для утвердительных предложений (стиль 해요체). Ставится в конце предложения.\"},{\"type\":\"formula\",\"text\":\"[слово] + 이에요 / 예요\"},{\"type\":\"rule\",\"text\":\"Есть 받침 (согласная внизу) → 이에요. Нет 받침 (чистая гласная) → 예요. Смотри на последнюю букву слова перед окончанием.\"},{\"type\":\"table\",\"head\":[\"Слово\",\"받침?\",\"Форма\",\"Пример\"],\"rows\":[[\"친구\",\"нет\",\"예요\",\"친구예요\"],[\"고기\",\"нет\",\"예요\",\"고기예요\"],[\"학생\",\"есть (ㅇ)\",\"이에요\",\"학생이에요\"],[\"사람\",\"есть (ㅁ)\",\"이에요\",\"사람이에요\"],[\"물\",\"есть (ㄹ)\",\"이에요\",\"물이에요\"]]},{\"type\":\"heading\",\"text\":\"Примеры\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"책이에요.\",\"ru\":\"Это книга.\"},{\"ko\":\"커피예요.\",\"ru\":\"Это кофе.\"},{\"ko\":\"저는 학생이에요.\",\"ru\":\"Я студент.\"},{\"ko\":\"저는 친구예요.\",\"ru\":\"Я друг.\"},{\"ko\":\"이것은 물이에요.\",\"ru\":\"Это вода.\"},{\"ko\":\"이것은 사과예요.\",\"ru\":\"Это яблоко.\"}]},{\"type\":\"pronunciation\",\"text\":\"연음: 책이에요 читается «че-ги-е-ё» — согласная из 받침 «переезжает» в начало следующего слога, у которого нет своей согласной (ㅇ).\"},{\"type\":\"tip\",\"text\":\"Метки в примерах: жирный с подчёркиванием = у слова ЕСТЬ 받침, просто жирный = у слова НЕТ 받침. Так же работают 은/는, 이/가, 을/를.\"},{\"type\":\"text\",\"text\":\"Слова урока 1: 커피, 의자, 책, 꽃, 저/나 (я — вежливо / разговорно), 이름, 뭐, 회사원. В уроке 4 диалога: как зовут, откуда ты, про студента и работу.\"}]},\n{\"id\":\"eun\",\"ko\":\"은 / 는\",\"ru\":\"частица темы\",\"section\":\"Частицы\",\"lesson\":\"Урок 2\",\"about\":\"«а что касается…» — о чём идёт речь\",\"blocks\":[{\"type\":\"text\",\"text\":\"Показывает, о чём или о ком идёт речь («а вот это…»). Обычно стоит после первого слова в предложении. ≈ «я / это (тема разговора)».\"},{\"type\":\"formula\",\"text\":\"[тема] + 은 / 는\"},{\"type\":\"rule\",\"text\":\"Есть 받침 → 은. Нет 받침 → 는. Правило то же, что у 이에요/예요 — только применяется в начале предложения, а не в конце.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"형은 …\",\"ru\":\"старший брат (тема)\"},{\"ko\":\"아빠는 …\",\"ru\":\"папа (тема)\"},{\"ko\":\"저는 학생이에요.\",\"ru\":\"Я студент.\"},{\"ko\":\"이것은 책이에요.\",\"ru\":\"Это книга.\"},{\"ko\":\"저는 학생이 아니에요.\",\"ru\":\"Я не студент.\"}]},{\"type\":\"tip\",\"text\":\"Чем 은/는 отличается от 이/가 — смотри карточку «이 / 가». Правило по 받침 одинаковое, разница в смысле.\"},{\"type\":\"text\",\"text\":\"Слова урока 2: 형, 동생, 아빠, 엄마, 가수, 회사원, 요리사. Задание на составление предложений (나/학생, 친구/가수 и т.д.).\"}]},\n{\"id\":\"iga\",\"ko\":\"이 / 가\",\"ru\":\"частица подлежащего\",\"section\":\"Частицы\",\"lesson\":\"Урок 3\",\"about\":\"«кто / что именно»\",\"blocks\":[{\"type\":\"text\",\"text\":\"Выделяет подлежащее: «кто/что именно» делает действие или является предметом разговора. Часто стоит в вопросах или когда называешь что-то впервые.\"},{\"type\":\"formula\",\"text\":\"[подлежащее] + 이 / 가\"},{\"type\":\"rule\",\"text\":\"Есть 받침 → 이. Нет 받침 → 가.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"이름이 뭐예요?\",\"ru\":\"Как тебя зовут?\"},{\"ko\":\"카페가 어디예요?\",\"ru\":\"Где кафе?\"},{\"ko\":\"이 사람이 누구예요?\",\"ru\":\"Кто этот человек?\"},{\"ko\":\"비가 와요.\",\"ru\":\"Идёт дождь.\"},{\"ko\":\"친구가 있어요.\",\"ru\":\"Есть друг.\"}]},{\"type\":\"tip\",\"text\":\"은/는 vs 이/가: правило по 받침 одинаковое, разница в смысле. 은/는 — «а вот об этом человеке/предмете» (тема, уже известное). 이/가 — «именно этот» (называешь новое, отвечаешь на вопрос, или сам вопрос «кто/что»). Вопросы и слова 있다/없다 почти всегда просят 이/가.\"},{\"type\":\"warning\",\"text\":\"Не путай с указательным 이 «этот» и с 이 в 이에요 — это разные 이, см. карточку «이 / 그 / 저».\"},{\"type\":\"text\",\"text\":\"Слова урока 3: 직업, 카페, 여기, 어디, 누구. 4 диалога: имя, профессия, где кафе, кто это.\"}]},\n{\"id\":\"anie\",\"ko\":\"이 아니에요 / 가 아니에요\",\"ru\":\"не являться («это не…», «я не…»)\",\"section\":\"Быть и отрицание\",\"lesson\":\"Урок 4\",\"about\":\"отрицание от 이에요/예요\",\"blocks\":[{\"type\":\"text\",\"text\":\"Отрицательная форма от 이에요/예요 — «это не… / я не…».\"},{\"type\":\"formula\",\"text\":\"[слово] + 이 / 가 아니에요\"},{\"type\":\"rule\",\"text\":\"Есть 받침 → 이 아니에요. Нет 받침 → 가 아니에요.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"동생이 아니에요.\",\"ru\":\"Это не младший/ая.\"},{\"ko\":\"누나가 아니에요.\",\"ru\":\"Это не старшая сестра.\"},{\"ko\":\"저는 학생이 아니에요.\",\"ru\":\"Я не студент.\"},{\"ko\":\"일본 사람이 아니에요.\",\"ru\":\"Я не японец.\"},{\"ko\":\"저는 한국 사람이 아니에요.\",\"ru\":\"Я не кореец.\"}]},{\"type\":\"warning\",\"text\":\"아니에요 не сокращается — читается полностью «а-ни-е-ё».\"},{\"type\":\"tip\",\"text\":\"С 이에요/예요 и 있어요/없어요 частицу 안 не используют: для «быть» отрицание — 이/가 아니에요.\"},{\"type\":\"text\",\"text\":\"Слова урока 4: 일본, 누나/언니 (старшая сестра: 누나 говорит парень, 언니 — девушка), 남자.\"}]},\n{\"id\":\"iss\",\"ko\":\"에 있다 / 에 없다\",\"ru\":\"есть / нет (о месте)\",\"section\":\"Место и направление\",\"lesson\":\"Урок 5\",\"about\":\"что где находится\",\"blocks\":[{\"type\":\"text\",\"text\":\"있다 — быть, находиться, 없다 — отсутствовать. С частицей 에 (место) показывает, есть что-то или кто-то в месте или нет. «Есть» о предмете почти всегда с 이/가 (не 은/는).\"},{\"type\":\"formula\",\"text\":\"[место] + 에 + [предмет] + 이/가 + 있어요 / 없어요\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"침대가 있어요.\",\"ru\":\"Кровать есть.\"},{\"ko\":\"지갑에 돈이 없어요.\",\"ru\":\"В кошельке нет денег.\"},{\"ko\":\"교실에 학생이 있어요.\",\"ru\":\"В классе есть ученик.\"},{\"ko\":\"집에 고양이가 있어요.\",\"ru\":\"Дома есть кошка.\"},{\"ko\":\"나나 씨는 학교에 있어요.\",\"ru\":\"Нана в школе.\"},{\"ko\":\"은행은 백화점 앞에 있어요.\",\"ru\":\"Банк перед универмагом.\"}]},{\"type\":\"rule\",\"text\":\"에 от 받침 не меняется: 학교에, 백화점에 — всегда 에.\"},{\"type\":\"warning\",\"text\":\"Частая ошибка: пропускать 에 после места.\"},{\"type\":\"pronunciation\",\"text\":\"학교에 있어요 [학꾜에 이써요], 없어요 [업써요]\"},{\"type\":\"tip\",\"text\":\"이/가 тут — та же частица подлежащего (карточка «이 / 가»), а не 은/는: называем предмет впервые, отвечаем на «что/кто есть».\"},{\"type\":\"text\",\"text\":\"Слова урока 5: 침대, 방, 지갑, 돈, 교실, 학생들 (показатель мн. числа 들), 옆에. Диалог про кровать + предложения про кошелёк/деньги, брата дома, учеников в классе.\"}]},\n{\"id\":\"ayo\",\"ko\":\"아요 / 어요 / 여요\",\"ru\":\"вежливое настоящее время\",\"section\":\"Глаголы и просьбы\",\"lesson\":\"Урок 6\",\"about\":\"глаголы: убираем 다, добавляем окончание\",\"blocks\":[{\"type\":\"text\",\"text\":\"У словарной формы убирается 다, добавляется одно из трёх окончаний — по последней гласной основы (а не по 받침!). Это единственное правило, которое не смотрит на 받침.\"},{\"type\":\"rule\",\"text\":\"Основа на ㅏ или ㅗ → 아요 Основа на любую другую гласную → 어요 Глаголы на 하다 → 해요 (не «하여요»)\"},{\"type\":\"table\",\"head\":[\"Словарная форма\",\"Вежливая форма\",\"Значение\"],\"rows\":[[\"많다\",\"많아요\",\"много\"],[\"먹다\",\"먹어요\",\"ем / кушаю\"],[\"공부하다\",\"공부해요\",\"учусь\"],[\"보다\",\"봐요\",\"смотрю (보+아요 → 봐요)\"],[\"오다\",\"와요\",\"прихожу (오+아요 → 와요)\"],[\"가다\",\"가요\",\"иду\"],[\"자다\",\"자요\",\"сплю\"],[\"사다\",\"사요\",\"покупаю\"],[\"배우다\",\"배워요\",\"учусь\"],[\"마시다\",\"마셔요\",\"пью\"],[\"쓰다\",\"써요\",\"пишу\"],[\"느리다\",\"느려요\",\"медленный\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"아야나는 자요.\",\"ru\":\"Аяна спит.\"},{\"ko\":\"테오는 샌드위치를 먹어요.\",\"ru\":\"Тео ест сэндвич.\"},{\"ko\":\"저는 책을 읽어요.\",\"ru\":\"Я читаю книгу.\"}]},{\"type\":\"warning\",\"text\":\"Гласные сливаются: 사다→사요, 보다→봐요; корейцы никогда не говорят несжатый вариант. Неправильные: 듣다→들어요 (ㄷ-неправильный, 받침 меняется), 덥다→더워요 (ㅂ-неправильный, 받침 исчезает и превращается в 워). Их нужно запоминать по одному.\"},{\"type\":\"pronunciation\",\"text\":\"먹어요 [머거요] (연음), 와요 [와요], 해요 [해요]\"},{\"type\":\"text\",\"text\":\"Слова урока 6: 많다, 좋다, 먹다, 읽다, 말하다, 앉다, 듣다, 덥다, 살다, 보다, 느리다, 사다, 지루하다. 3 диалога: про яблоки (무엇이 있어요?), про еду (밥 먹어요?), про человека (이 사람은 누구예요?) + предложения про школу/работу.\"}]},\n{\"id\":\"adj\",\"ko\":\"형용사 + 아요 / 어요\",\"ru\":\"прилагательные «какой?»\",\"section\":\"Глаголы и просьбы\",\"lesson\":\"\",\"about\":\"прилагательное — это глагол состояния\",\"blocks\":[{\"type\":\"text\",\"text\":\"Прилагательное — это глагол состояния: к основе добавляют -아요/어요, и получается вежливое «вкусный, дорогой, чистый». Предмет описания берёт 이/가.\"},{\"type\":\"rule\",\"text\":\"Последняя гласная основы ㅏ, ㅗ → -아요. Остальные → -어요. На -하다 → 해요. Существительное перед прилагательным: есть 받침 → 이, нет → 가.\"},{\"type\":\"table\",\"head\":[\"Основа\",\"Окончание\",\"Результат\"],\"rows\":[[\"좋\",\"ㅗ → 아요\",\"좋아요\"],[\"맛있\",\"ㅣ → 어요\",\"맛있어요\"],[\"친절하\",\"하다 → 해요\",\"친절해요\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"사과가 비싸요.\",\"ru\":\"Яблоки дорогие.\"},{\"ko\":\"교실이 깨끗해요.\",\"ru\":\"Класс чистый.\"},{\"ko\":\"명동에 사람이 많아요? — 네, 많아요.\",\"ru\":\"В Мёндоне много людей? — Да, много.\"}]},{\"type\":\"tip\",\"text\":\"Вопрос и ответ звучат одинаково — меняется интонация: 많아요? — 네, 많아요.\"}]},\n{\"id\":\"an\",\"ko\":\"안 + 아요 / 어요 / 여요\",\"ru\":\"отрицание глаголов\",\"section\":\"Быть и отрицание\",\"lesson\":\"Урок 7\",\"about\":\"«не делаю», «не такой»\",\"blocks\":[{\"type\":\"text\",\"text\":\"안 ставится ПЕРЕД глаголом или прилагательным и превращает его в отрицание «не…». Окончание выбирается по тому же правилу, что в «아요/어요».\"},{\"type\":\"formula\",\"text\":\"안 + [глагол в вежливой форме]\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"안 많아요.\",\"ru\":\"Не много.\"},{\"ko\":\"안 먹어요.\",\"ru\":\"Не ем.\"},{\"ko\":\"안 해요.\",\"ru\":\"Не делаю.\"},{\"ko\":\"저는 드라마를 안 봐요.\",\"ru\":\"Я не смотрю дораму.\"},{\"ko\":\"방이 안 깨끗해요.\",\"ru\":\"Комната не чистая.\"},{\"ko\":\"오늘 일해요? — 아니요, 일 안 해요.\",\"ru\":\"Сегодня работаешь? — Нет, не работаю.\"}]},{\"type\":\"warning\",\"text\":\"Три исключения. 1) Длинная форма: 안+слово = слово-지 않아요 (оба верны): 가지 않아요 = 안 가요. 2) Составные [сущ.]+하다: 안 встаёт ВНУТРИ, перед 하다: 공부 안 해요 (не 안 공부해요), 청소 안 해요. Исключение: 좋아하다 → 안 좋아해요. 3) Слова с готовым антонимом: 알다→모르다 (몰라요), 있다→없다 (없어요).\"},{\"type\":\"tip\",\"text\":\"Не используется с 이에요/예요 (там 이/가 아니에요) и с 있어요/없어요.\"},{\"type\":\"text\",\"text\":\"Слова урока 7: 지금, 음악, 여러분, 운동하다, 숙제, 일기, 쓰다, 매일, 알다, 모르다, 청소하다, 피곤하다.\"}]},\n{\"id\":\"eul\",\"ko\":\"을 / 를\",\"ru\":\"частица прямого дополнения\",\"section\":\"Частицы\",\"lesson\":\"Урок 8\",\"about\":\"на что направлено действие\",\"blocks\":[{\"type\":\"text\",\"text\":\"Показывает, НА ЧТО направлено действие — «что именно» делают, «кого/что».\"},{\"type\":\"formula\",\"text\":\"[объект] + 을 / 를 + [действие]\"},{\"type\":\"rule\",\"text\":\"Есть 받침 → 을. Нет 받침 → 를.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"책을 읽어요.\",\"ru\":\"Читаю книгу.\"},{\"ko\":\"커피를 마셔요.\",\"ru\":\"Пью кофе.\"},{\"ko\":\"편지를 써요.\",\"ru\":\"Пишу письмо.\"},{\"ko\":\"저는 커피를 사요.\",\"ru\":\"Я покупаю кофе.\"},{\"ko\":\"저는 빵을 만들어요.\",\"ru\":\"Я делаю хлеб.\"}]},{\"type\":\"tip\",\"text\":\"뭐 vs 무엇: оба «что» — два варианта одного слова. 뭐 — разговорная короткая форма, 무엇 — формальная. После 뭐 частицу 를 часто опускают (뭐 해요? — норма). С 무엇 частицу не опускают (무엇을 해요?). 뭘 = стянутое 뭐+를.\"},{\"type\":\"text\",\"text\":\"Слова урока 8: 편지, 노래, 영화, 라면, 여행.\"}]},\n{\"id\":\"gada\",\"ko\":\"에 가다\",\"ru\":\"идти / приходить в место\",\"section\":\"Место и направление\",\"lesson\":\"Урок 9\",\"about\":\"направление: куда идём\",\"blocks\":[{\"type\":\"formula\",\"text\":\"[место] + 에 + 가요 / 와요\"},{\"type\":\"rule\",\"text\":\"가다 — движение ОТ говорящего. 오다 — движение К говорящему. Если говорящий уже находится в месте назначения, говорят 와요. 에 нельзя пропускать, от 받침 не меняется.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"크리스는 식당에 가요.\",\"ru\":\"Крис идёт в ресторан.\"},{\"ko\":\"학교에 가요.\",\"ru\":\"Иду в школу.\"},{\"ko\":\"친구가 집에 와요.\",\"ru\":\"Друг приходит домой.\"},{\"ko\":\"병원에 가요.\",\"ru\":\"Иду в больницу.\"}]},{\"type\":\"warning\",\"text\":\"Неверно: 백화점 가요 ✗ → верно: 백화점에 가요 ✓\"},{\"type\":\"pronunciation\",\"text\":\"식당에 가요 [식땅에 가요]. 오다 → 와요 (ㅗ + 아 сливаются в 와).\"}]},\n{\"id\":\"eseo\",\"ko\":\"에서\",\"ru\":\"место действия\",\"section\":\"Место и направление\",\"lesson\":\"Урок 10\",\"about\":\"где что-то делают\",\"blocks\":[{\"type\":\"formula\",\"text\":\"[место] + 에서 + [глагол действия]\"},{\"type\":\"text\",\"text\":\"Отвечает на вопрос «где происходит действие». От 받침 не зависит — всегда 에서.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"안나는 도서관에서 공부해요.\",\"ru\":\"Анна учится в библиотеке.\"},{\"ko\":\"식당에서 밥을 먹어요.\",\"ru\":\"Ем в столовой.\"},{\"ko\":\"공원에서 운동해요.\",\"ru\":\"Занимаюсь спортом в парке.\"},{\"ko\":\"카페에서 아르바이트해요.\",\"ru\":\"Подрабатываю в кафе.\"}]},{\"type\":\"heading\",\"text\":\"Сравни: 에 или 에서?\"},{\"type\":\"table\",\"head\":[\"После слова места…\",\"Частица\"],\"rows\":[[\"있어요 / 없어요 или 가요 / 와요\",\"에\"],[\"глагол действия (공부해요, 먹어요, 운동해요)\",\"에서\"]]},{\"type\":\"pronunciation\",\"text\":\"도서관에서 [도서과네서]: ㄴ из 관 переезжает к 에 (연음).\"}]},\n{\"id\":\"hago\",\"ko\":\"하고\",\"ru\":\"«и» между существительными\",\"section\":\"Частицы\",\"lesson\":\"\",\"about\":\"соединяет слова: вода и сок\",\"blocks\":[{\"type\":\"formula\",\"text\":\"[сущ.] + 하고 + [сущ.]\"},{\"type\":\"text\",\"text\":\"Соединяет слова как «и». От 받침 не зависит — всегда 하고. Частица (이/가, 을/를) ставится один раз, после последнего слова.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"물하고 주스\",\"ru\":\"вода и сок\"},{\"ko\":\"빵하고 커피\",\"ru\":\"хлеб и кофе\"},{\"ko\":\"물하고 주스가 있어요.\",\"ru\":\"Есть вода и сок.\"},{\"ko\":\"빵하고 커피 주세요.\",\"ru\":\"Дайте хлеб и кофе.\"},{\"ko\":\"우리 반 친구들하고 같이 학생 식당에 가요.\",\"ru\":\"Мы с одногруппниками идём в студенческую столовую.\"}]},{\"type\":\"pronunciation\",\"text\":\"물하고 [мульхаго], 빵하고 [ппанхаго].\"},{\"type\":\"tip\",\"text\":\"В уроке 11 по курсу — 와/과 (вариант по 받침). Конспекта урока пока нет.\"}]},\n{\"id\":\"pos\",\"ko\":\"앞 / 뒤 / 옆 / 위 / 아래\",\"ru\":\"слова положения\",\"section\":\"Место и направление\",\"lesson\":\"\",\"about\":\"перед, за, рядом, над, под\",\"blocks\":[{\"type\":\"formula\",\"text\":\"[сущ.] + 앞 / 뒤 / 옆 / 위 / 아래 + 에 + 있어요\"},{\"type\":\"rule\",\"text\":\"Слово положения стоит ПОСЛЕ существительного («банк-перед»), а 에 — после слова положения: 백화점 앞에.\"},{\"type\":\"table\",\"head\":[\"Слово\",\"Значение\"],\"rows\":[[\"앞\",\"перед\"],[\"뒤\",\"за, сзади\"],[\"옆\",\"рядом, сбоку\"],[\"위\",\"над, на\"],[\"아래 (밑)\",\"под, низ\"],[\"안\",\"внутри\"],[\"밖\",\"снаружи\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"은행은 백화점 앞에 있어요.\",\"ru\":\"Банк перед универмагом.\"},{\"ko\":\"학교 뒤에 공원이 있어요.\",\"ru\":\"За школой есть парк.\"},{\"ko\":\"병원 옆에 약국이 있어요.\",\"ru\":\"Рядом с больницей аптека.\"},{\"ko\":\"책상 위에 책이 있어요.\",\"ru\":\"На столе книга.\"},{\"ko\":\"의자 아래에 가방이 있어요.\",\"ru\":\"Под стулом сумка.\"},{\"ko\":\"가방 안에 책이 있어요.\",\"ru\":\"В сумке книга.\"},{\"ko\":\"교실 밖에 있어요.\",\"ru\":\"Снаружи класса.\"}]},{\"type\":\"pronunciation\",\"text\":\"앞에 [아페], 옆에 [여페]: последняя согласная переезжает к 에 (연음).\"},{\"type\":\"warning\",\"text\":\"안 «внутри» — не то же самое, что частица отрицания 안 (см. «안 + 아요/어요»).\"}]},\n{\"id\":\"here\",\"ko\":\"여기 / 거기 / 저기\",\"ru\":\"здесь / там / вон там\",\"section\":\"Место и направление\",\"lesson\":\"\",\"about\":\"указатели места\",\"blocks\":[{\"type\":\"table\",\"head\":[\"Слово\",\"Значение\"],\"rows\":[[\"여기 [ёги]\",\"здесь, рядом с говорящим\"],[\"거기 [коги]\",\"там, рядом с собеседником или то, о чём уже сказали\"],[\"저기 [чоги]\",\"вон там, далеко от обоих\"]]},{\"type\":\"text\",\"text\":\"Частицы по обычному правилу: слова кончаются на гласную, значит 가, 는, 를. 에 не меняется.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"저기에 은행이 있어요.\",\"ru\":\"Вон там банк.\"},{\"ko\":\"카페가 여기예요.\",\"ru\":\"Кафе здесь.\"},{\"ko\":\"거기에 가방이 있어요.\",\"ru\":\"Там сумка.\"},{\"ko\":\"지하철역은 저기에 있어요.\",\"ru\":\"Станция метро вон там.\"}]}]},\n{\"id\":\"deul\",\"ko\":\"들\",\"ru\":\"множественное число\",\"section\":\"Частицы\",\"lesson\":\"\",\"about\":\"친구 → 친구들 (несколько)\",\"blocks\":[{\"type\":\"text\",\"text\":\"Существительное + 들. Показывает «несколько», а не слово «много». 들 читается «тыль».\"},{\"type\":\"rule\",\"text\":\"들 заканчивается на ㄹ (받침 есть), поэтому после него идут 은 / 이 / 을, а не 는 / 가 / 를.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"친구들은 학교에 가요.\",\"ru\":\"Друзья идут в школу.\"},{\"ko\":\"학생들이 도서관에서 숙제해요.\",\"ru\":\"Ученики делают домашнее задание в библиотеке.\"},{\"ko\":\"저는 친구를 만나요.\",\"ru\":\"Я встречаюсь с другом.\"}]},{\"type\":\"pronunciation\",\"text\":\"친구들은 [чингудырын], 친구들이 [чингудыри], 친구들을 [чингудырыль].\"},{\"type\":\"warning\",\"text\":\"Ошибка: 친구들는 ✗ → 친구들은 ✓. С числом 들 обычно не нужен (친구 둘 — два друга); если и так ясно, что их много, 들 часто опускают. Глагол по числу не меняется: 가요 и для «друг идёт», и для «друзья идут».\"}]},\n{\"id\":\"nuga\",\"ko\":\"누구 vs 누가\",\"ru\":\"«кто» в двух формах\",\"section\":\"Указатели и вопросы\",\"lesson\":\"\",\"about\":\"сказуемое или подлежащее\",\"blocks\":[{\"type\":\"text\",\"text\":\"Одно слово 누구 (кто) в двух формах — базовой и с частицей подлежащего.\"},{\"type\":\"rule\",\"text\":\"«Кто» — сказуемое (после «это/этот», перед 예요) → 누구. «Кто» — сам действует (подлежащее, перед глаголом) → 누가 (누구+가, особое стяжение, 구 выпадает).\"},{\"type\":\"tip\",\"text\":\"Быстрая проверка: поставь вопрос по-русски и посмотри, что идёт сразу после «кто»: глагол → 누가. Связка «это/есть» → 누구.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"이 사람이 누구예요?\",\"ru\":\"Кто этот человек?\"},{\"ko\":\"누가 책을 읽어요?\",\"ru\":\"Кто читает книгу?\"},{\"ko\":\"누가 음악을 안 들어요?\",\"ru\":\"Кто не слушает музыку?\"},{\"ko\":\"저 사람이 누구예요?\",\"ru\":\"Кто тот человек вон там?\"},{\"ko\":\"이것은 누구의 가방이에요?\",\"ru\":\"Чья это сумка?\"}]}]},\n{\"id\":\"ijeo\",\"ko\":\"이 / 그 / 저\",\"ru\":\"указательные и 이것 / 그것 / 저것\",\"section\":\"Указатели и вопросы\",\"lesson\":\"\",\"about\":\"«этот», «тот», «вон тот»\",\"blocks\":[{\"type\":\"text\",\"text\":\"Это слова «этот / тот», совсем другое, чем частица подлежащего 이.\"},{\"type\":\"heading\",\"text\":\"Перед существительным\"},{\"type\":\"table\",\"head\":[\"Слово\",\"Значение\",\"Пример\"],\"rows\":[[\"이\",\"этот, рядом со мной\",\"이 책 — эта книга\"],[\"그\",\"тот / этот, рядом с собеседником или уже известный\",\"그 책 — та книга\"],[\"저\",\"вон тот, далеко от обоих\",\"저 책 — та книга вон там\"]]},{\"type\":\"heading\",\"text\":\"Самостоятельно: «эта вещь»\"},{\"type\":\"text\",\"text\":\"것 = вещь, предмет. 이+것 = 이것 (разговорно 이거) — эта вещь рядом со мной. 그것 (그거) — та вещь у собеседника. 저것 (저거) — та вещь далеко.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"이 사람\",\"ru\":\"этот человек (рядом со мной)\"},{\"ko\":\"이거 뭐예요?\",\"ru\":\"Что это? (вещь в твоей руке)\"},{\"ko\":\"그거 커피예요?\",\"ru\":\"Это у тебя кофе?\"},{\"ko\":\"저 호텔\",\"ru\":\"тот отель вон там\"}]},{\"type\":\"warning\",\"text\":\"Четыре разных 이, которые просто одинаково пишутся:\"},{\"type\":\"table\",\"head\":[\"Что это за 이\",\"Пример\",\"Разбор\"],\"rows\":[[\"1) Указательное «этот»\",\"이 사람이 누구예요?\",\"первое 이 — самостоятельное слово, стоит ПЕРЕД существительным\"],[\"2) Частица подлежащего\",\"이 사람이 누구예요?\",\"второе 이 приклеено к 사람 (есть 받침 ㅁ)\"],[\"3) Часть окончания 이에요\",\"책이에요.\",\"кусок окончания «быть», отдельно не выделяется\"],[\"4) Часть слова 이것/이거\",\"이것은 책이에요.\",\"цельное местоимение «эта вещь»\"]]},{\"type\":\"correct\",\"text\":\"Как отличить: после 이 стоит существительное (이 사람) — указательное «этот». 이 приклеено К КОНЦУ слова (사람이, 책이에요) — частица или окончание. Целое слово 이것/이거 отдельно — местоимение.\"}]},\n{\"id\":\"juse\",\"ko\":\"주세요\",\"ru\":\"«дайте, пожалуйста»\",\"section\":\"Глаголы и просьбы\",\"lesson\":\"\",\"about\":\"вежливая просьба в кафе и магазине\",\"blocks\":[{\"type\":\"formula\",\"text\":\"[сущ.] + 주세요\"},{\"type\":\"text\",\"text\":\"Вежливая просьба дать или сделать что-то — очень частая в ресторанах и магазинах.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"물 주세요.\",\"ru\":\"Дайте воды, пожалуйста.\"},{\"ko\":\"메뉴 주세요.\",\"ru\":\"Дайте меню.\"},{\"ko\":\"이거 주세요.\",\"ru\":\"Дайте вот это.\"},{\"ko\":\"포크 주세요.\",\"ru\":\"Дайте вилку.\"},{\"ko\":\"빵하고 커피 주세요.\",\"ru\":\"Дайте хлеб и кофе.\"},{\"ko\":\"커피 두 잔 주세요.\",\"ru\":\"Два кофе, пожалуйста.\"},{\"ko\":\"비빔밥 한 그릇 주세요.\",\"ru\":\"Одну порцию бибимбапа.\"},{\"ko\":\"물 세 병 주세요.\",\"ru\":\"Три бутылки воды.\"}]},{\"type\":\"pronunciation\",\"text\":\"물 주세요 [муль чусеё], 메뉴 주세요 [меню чусеё], 이거 주세요 [иго чусеё].\"},{\"type\":\"tip\",\"text\":\"Счётные слова 잔, 병, 그릇 — в разделе «Числа».\"}]},\n{\"id\":\"past\",\"ko\":\"았어요 / 었어요 / 였어요\",\"ru\":\"прошедшее время\",\"section\":\"Время\",\"lesson\":\"Урок 16-1\",\"about\":\"что было, что сделал\",\"blocks\":[{\"type\":\"text\",\"text\":\"Так говорят о том, что уже было: «ел», «ходил», «читал». К основе глагола или прилагательного добавляется 았어요, 었어요 или (у глаголов на 하다) 했어요. Время (어제, 지난주, 아침에) обычно ставят в начало.\"},{\"type\":\"formula\",\"text\":\"основа + 았어요 / 었어요; 하다 → 했어요\"},{\"type\":\"rule\",\"text\":\"Последняя гласная основы ㅏ или ㅗ → 았어요: 가 → 갔어요, 오 → 왔어요, 앉 → 앉았어요. Любая другая гласная → 었어요: 먹 → 먹었어요, 읽 → 읽었어요. Глаголы на 하다 → 했어요: 공부하다 → 공부했어요.\"},{\"type\":\"pronunciation\",\"text\":\"Выбор между 았 и 었 зависит от гласной основы, а не от 받침. Если основа кончается на гласную, она сливается с 았 / 었 в один слог: 가 + 았어요 = 갔어요, 마시 + 었어요 = 마셨어요.\"},{\"type\":\"table\",\"head\":[\"Глагол\",\"Прошедшее\",\"Перевод\",\"Как получилось\"],\"rows\":[[\"가다\",\"갔어요\",\"ходил(а), поехал(а)\",\"가 + 았어요 → 갔어요\"],[\"오다\",\"왔어요\",\"пришёл, пришла\",\"오 + 았어요 → 왔어요\"],[\"보다\",\"봤어요\",\"видел(а), смотрел(а)\",\"보 + 았어요 → 봤어요\"],[\"사다\",\"샀어요\",\"купил(а)\",\"사 + 았어요 → 샀어요\"],[\"만나다\",\"만났어요\",\"встретил(а)\",\"만나 + 았어요 → 만났어요\"],[\"자다\",\"잤어요\",\"спал(а)\",\"자 + 았어요 → 잤어요\"],[\"앉다\",\"앉았어요\",\"сел(а)\",\"앉 + 았어요 (последняя гласная ㅏ)\"],[\"좋다\",\"좋았어요\",\"было хорошо\",\"좋 + 았어요 (последняя гласная ㅗ)\"],[\"먹다\",\"먹었어요\",\"ел(а)\",\"먹 + 었어요\"],[\"읽다\",\"읽었어요\",\"читал(а)\",\"읽 + 었어요\"],[\"마시다\",\"마셨어요\",\"пил(а)\",\"마시 + 었어요 → 마셨어요\"],[\"쉬다\",\"쉬었어요\",\"отдыхал(а)\",\"쉬 + 었어요\"],[\"배우다\",\"배웠어요\",\"учился, учила\",\"배우 + 었어요 → 배웠어요\"],[\"주다\",\"줬어요\",\"дал(а)\",\"주 + 었어요 → 줬어요\"],[\"쓰다\",\"썼어요\",\"писал(а)\",\"쓰 + 었어요 → 썼어요 (ㅡ выпадает)\"],[\"있다\",\"있었어요\",\"был(а), находился\",\"있 + 었어요\"],[\"하다\",\"했어요\",\"делал(а)\",\"하 + 였어요 → 했어요\"],[\"공부하다\",\"공부했어요\",\"учился, учила\",\"공부하다 → 공부했어요\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"어제 친구를 만났어요.\",\"ru\":\"Вчера я встретил(а) друга.\"},{\"ko\":\"지난주에 영화를 봤어요.\",\"ru\":\"На прошлой неделе я смотрел(а) фильм.\"},{\"ko\":\"아침에 빵을 먹었어요.\",\"ru\":\"Утром я ел(а) хлеб.\"},{\"ko\":\"어제 도서관에서 책을 읽었어요.\",\"ru\":\"Вчера я читал(а) книгу в библиотеке.\"},{\"ko\":\"주말에 집에서 쉬었어요.\",\"ru\":\"В выходные я отдыхал(а) дома.\"},{\"ko\":\"저는 어제 한국어를 공부했어요.\",\"ru\":\"Вчера я учил(а) корейский.\"},{\"ko\":\"친구가 학교에 왔어요.\",\"ru\":\"Друг пришёл в школу.\"},{\"ko\":\"어제 커피를 마셨어요.\",\"ru\":\"Вчера я пил(а) кофе.\"},{\"ko\":\"일요일에 시장에서 과일을 샀어요.\",\"ru\":\"В воскресенье я купил(а) фрукты на рынке.\"},{\"ko\":\"어제는 날씨가 좋았어요.\",\"ru\":\"Вчера была хорошая погода.\"}]},{\"type\":\"warning\",\"text\":\"먹았어요 (×) → 먹었어요 (○). Решает последняя гласная основы: у 먹 это ㅓ, поэтому 었어요, а не 았어요.\"},{\"type\":\"warning\",\"text\":\"가었어요 (×), 가았어요 (×) → 갔어요 (○). Если основа кончается на гласную, 았 / 었 сливаются с ней в один слог: 가 + 았 = 갔.\"},{\"type\":\"warning\",\"text\":\"하았어요 (×), 하었어요 (×) → 했어요 (○). У глаголов на 하다 всегда 했어요: 공부했어요, 일했어요, 운동했어요.\"},{\"type\":\"heading\",\"text\":\"Сравни: сейчас и раньше\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"가요. / 갔어요.\",\"ru\":\"Иду. / Ходил(а).\"},{\"ko\":\"먹어요. / 먹었어요.\",\"ru\":\"Ем. / Ел(а).\"},{\"ko\":\"공부해요. / 공부했어요.\",\"ru\":\"Учусь. / Учился, училась.\"},{\"ko\":\"지금 학교에 있어요. / 어제 학교에 있었어요.\",\"ru\":\"Сейчас в школе. / Вчера был(а) в школе.\"}]},{\"type\":\"tip\",\"text\":\"Вопрос о прошлом: 어제 뭐 했어요? — «Что вы делали вчера?» Ответ: 친구를 만났어요. А «был(а) кем-то» говорят иначе: 학생이었어요 (смотри карточку «였어요 / 이었어요»).\"}]},\n{\"id\":\"past_i\",\"ko\":\"였어요 / 이었어요\",\"ru\":\"«был(а)» (прошедшее от 이에요)\",\"section\":\"Время\",\"lesson\":\"Урок 16-2\",\"about\":\"был(а) кем-то, чем-то\",\"blocks\":[{\"type\":\"text\",\"text\":\"Так говорят, кем или чем кто-то был: «был студентом», «было воскресенье». Это прошедшее время от связки 이에요 / 예요: после слова с 받침 — 이었어요, без 받침 — 였어요.\"},{\"type\":\"formula\",\"text\":\"слово + 이었어요 / 였어요\"},{\"type\":\"rule\",\"text\":\"Есть 받침 → 이었어요. Нет 받침 → 였어요. Правило по 받침 то же, что у 이에요 / 예요: 학생이에요 → 학생이었어요, 친구예요 → 친구였어요.\"},{\"type\":\"table\",\"head\":[\"Сейчас\",\"Раньше\",\"Перевод\"],\"rows\":[[\"학생이에요\",\"학생이었어요\",\"был(а) студентом\"],[\"선생님이에요\",\"선생님이었어요\",\"был(а) учителем\"],[\"회사원이에요\",\"회사원이었어요\",\"был(а) сотрудником компании\"],[\"일요일이에요\",\"일요일이었어요\",\"было воскресенье\"],[\"친구예요\",\"친구였어요\",\"был(а) другом\"],[\"가수예요\",\"가수였어요\",\"был(а) певцом, певицей\"],[\"의사예요\",\"의사였어요\",\"был(а) врачом\"],[\"요리사예요\",\"요리사였어요\",\"был(а) поваром\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"어제는 일요일이었어요.\",\"ru\":\"Вчера было воскресенье.\"},{\"ko\":\"그 사람은 제 친구였어요.\",\"ru\":\"Тот человек был моим другом.\"},{\"ko\":\"엄마는 가수였어요.\",\"ru\":\"Мама была певицей.\"},{\"ko\":\"우리 아빠는 선생님이었어요.\",\"ru\":\"Мой папа был учителем.\"},{\"ko\":\"저 사람은 의사였어요.\",\"ru\":\"Тот человек был врачом.\"},{\"ko\":\"어제가 시험이었어요.\",\"ru\":\"Экзамен был вчера.\"},{\"ko\":\"이것은 제 책이었어요.\",\"ru\":\"Это была моя книга.\"},{\"ko\":\"동생은 대학생이었어요.\",\"ru\":\"Младший брат или сестра были студентом (студенткой) университета.\"}]},{\"type\":\"warning\",\"text\":\"학생였어요 (×) → 학생이었어요 (○). После 받침 нужно 이었어요.\"},{\"type\":\"warning\",\"text\":\"친구이었어요 (×) → 친구였어요 (○). Без 받침 только 였어요 (친구예요 → 친구였어요).\"},{\"type\":\"heading\",\"text\":\"Сравни: сейчас и раньше\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"오늘은 월요일이에요. / 어제는 일요일이었어요.\",\"ru\":\"Сегодня понедельник. / Вчера было воскресенье.\"},{\"ko\":\"친구예요. / 친구였어요.\",\"ru\":\"Это друг. / Это был друг.\"}]},{\"type\":\"tip\",\"text\":\"«Не был(а)»: от 아니에요 образуется 아니었어요 (학생이 아니었어요 — «не был студентом»). С другими словами используется обычное прошедшее: 갔어요, 먹었어요 (карточка «았어요 / 었어요»).\"}]},\n{\"id\":\"when_e\",\"ko\":\"에 (когда): в пятницу, на выходных\",\"ru\":\"«когда?» — частица времени\",\"section\":\"Время\",\"lesson\":\"\",\"about\":\"в какой день и в какое время что-то происходит\",\"blocks\":[{\"type\":\"text\",\"text\":\"Частица 에 ставится после слова, которое отвечает на вопрос «когда?»: день недели, часть дня, неделя, выходные. По-русски это «в», «на» или просто наречие: в пятницу, на выходных, утром.\"},{\"type\":\"formula\",\"text\":\"[слово времени] + 에 + [действие]\"},{\"type\":\"rule\",\"text\":\"В корейском нет падежей: 금요일 — просто «пятница» (подлежащее). Чтобы сказать «в пятницу» (когда?), добавь 에. Она всегда одна и та же, 받침 не важен.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"금요일에 친구를 만나요.\",\"ru\":\"В пятницу встречаюсь с другом.\"},{\"ko\":\"토요일에 운동해요.\",\"ru\":\"В субботу занимаюсь спортом.\"},{\"ko\":\"주말에 파티에 가요.\",\"ru\":\"На выходных иду на вечеринку.\"},{\"ko\":\"아침에 커피를 마셔요.\",\"ru\":\"Утром пью кофе.\"},{\"ko\":\"평일에 학교에 가요.\",\"ru\":\"В будни хожу в школу.\"},{\"ko\":\"이번 주에 시간이 있어요?\",\"ru\":\"На этой неделе у тебя есть время?\"}]},{\"type\":\"heading\",\"text\":\"Вопрос и ответ\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"무슨 요일에 태권도를 배워요?\",\"ru\":\"В какой день недели ты учишь тхэквондо?\"},{\"ko\":\"수요일하고 금요일에 배워요.\",\"ru\":\"По средам и пятницам.\"},{\"ko\":\"금요일에 뭐 해요?\",\"ru\":\"Что делаешь в пятницу?\"},{\"ko\":\"영화를 봐요.\",\"ru\":\"Смотрю фильм.\"}]},{\"type\":\"heading\",\"text\":\"Какие слова времени берут 에\"},{\"type\":\"table\",\"head\":[\"Слова\",\"Что значат\",\"С 에?\"],\"rows\":[[\"월요일 화요일 수요일 목요일 금요일 토요일 일요일\",\"дни недели\",\"에\"],[\"평일 · 주말\",\"будни · выходные\",\"에\"],[\"아침 · 점심 · 저녁 · 밤\",\"утро · день · вечер · ночь\",\"에\"],[\"지난주 · 이번 주 · 다음 주\",\"прошлая · эта · следующая неделя\",\"에\"],[\"오늘 · 내일 · 지금 · 언제\",\"сегодня · завтра · сейчас · когда\",\"без 에\"]]},{\"type\":\"warning\",\"text\":\"Четыре слова идут БЕЗ 에: 오늘 (сегодня), 내일 (завтра), 지금 (сейчас), 언제 (когда). Неверно: 오늘에 한국어를 공부해요 (×). Верно: 오늘 한국어를 공부해요 (○).\"},{\"type\":\"tip\",\"text\":\"Слово 어제 (вчера) на практике тоже говорят без 에: 어제 도서관에 갔어요. В учебнике список из четырёх слов, 어제 добавлено для памяти.\"},{\"type\":\"tip\",\"text\":\"Не путай: 에 в «иду в школу» (куда?) и 에 в «в пятницу» (когда?) — это одна частица, но на разные вопросы. Если слово отвечает на «когда?», без 에 нельзя (кроме четырёх слов выше).\"},{\"type\":\"warning\",\"text\":\"Две частые ошибки. Забыл 에 после дня недели: 금요일 친구를 만나요 (×) → 금요일에 친구를 만나요 (○). 하고 пишется слитно, а 에 только в конце: 수요일 하고 금요일에 (×) → 수요일하고 금요일에 (○).\"},{\"type\":\"text\",\"text\":\"Порядок слов в предложении: время → кто → что → где → глагол. После слова на 받침 (금요일, 주말) 에 просто присоединяется. При чтении 받침 переходит на 에: 금요일에 читается [그묘이레].\"},{\"type\":\"heading\",\"text\":\"Сравни: 에 — место и время\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"학교에 가요.\",\"ru\":\"Иду в школу (место, куда).\"},{\"ko\":\"금요일에 가요.\",\"ru\":\"Иду в пятницу (время).\"},{\"ko\":\"금요일에 학교에 가요.\",\"ru\":\"В пятницу иду в школу.\"},{\"ko\":\"도서관에서 공부해요.\",\"ru\":\"Учусь в библиотеке (где действие: 에서).\"}]},{\"type\":\"heading\",\"text\":\"Дни недели\"},{\"type\":\"table\",\"head\":[\"День\",\"Чтение\",\"По-русски\"],\"rows\":[[\"월요일\",\"ворёиль\",\"понедельник\"],[\"화요일\",\"хваёиль\",\"вторник\"],[\"수요일\",\"суёиль\",\"среда\"],[\"목요일\",\"мокёиль\",\"четверг\"],[\"금요일\",\"кымнёиль\",\"пятница\"],[\"토요일\",\"тхоёиль\",\"суббота\"],[\"일요일\",\"ильёиль\",\"воскресенье\"]]},{\"type\":\"text\",\"text\":\"Слово 요일 значит «день недели», перед ним стоит слог с названием: 월 (луна), 화 (огонь), 수 (вода), 목 (дерево), 금 (металл, золото), 토 (земля), 일 (солнце). 평일 — будни (с понедельника по пятницу), 주말 — выходные (суббота и воскресенье). 지난주 — прошлая неделя, 이번 주 — эта, 다음 주 — следующая (слог 주 значит «неделя»).\"}]},\n{\"id\":\"too_do\",\"ko\":\"도 (тоже)\",\"ru\":\"«тоже» — добавление к сказанному\",\"section\":\"Частицы\",\"lesson\":\"\",\"about\":\"«я тоже», «и это тоже»\",\"blocks\":[{\"type\":\"text\",\"text\":\"Частица 도 ставится после существительного и значит «тоже»: к тому, что уже есть, добавляется что-то ещё.\"},{\"type\":\"formula\",\"text\":\"[слово] + 도\"},{\"type\":\"rule\",\"text\":\"도 ставят ВМЕСТО 은/는, 이/가, 을/를, а не вместе с ними. Неверно: 저는도 학생이에요 (×), 에릭 씨가도 학생이에요 (×). Верно: 저도 학생이에요 (○), 에릭 씨도 학생이에요 (○). От 받침 слова 도 не зависит.\"},{\"type\":\"table\",\"head\":[\"Что стояло бы без «тоже»\",\"Что ставим\",\"Пример\"],\"rows\":[[\"저는 (тема)\",\"저도\",\"저도 가요. — Я тоже иду.\"],[\"에릭 씨가 (подлежащее)\",\"에릭 씨도\",\"에릭 씨도 학생이에요. — Эрик тоже студент.\"],[\"불고기를 (объект)\",\"불고기도\",\"불고기도 좋아해요. — Пулькоги тоже люблю.\"],[\"토요일에 (когда)\",\"토요일에도\",\"일요일에도 친구를 만나요. — И в воскресенье встречаюсь.\"],[\"도서관에서 (где)\",\"도서관에서도\",\"카페에서도 공부해요. — И в кафе занимаюсь.\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"하이 씨도 주말에 파티에 가요?\",\"ru\":\"Хай, ты тоже идёшь на выходных на вечеринку?\"},{\"ko\":\"네, 저도 가요.\",\"ru\":\"Да, я тоже иду.\"},{\"ko\":\"교실에 중국 학생이 있어요. 미국 학생도 있어요.\",\"ru\":\"В классе есть китайский ученик. Американский ученик тоже есть.\"},{\"ko\":\"저는 비빔밥을 좋아해요. 불고기도 좋아해요.\",\"ru\":\"Я люблю бибимбап. Пулькоги тоже люблю.\"},{\"ko\":\"저는 토요일에 친구를 만나요. 일요일에도 친구를 만나요.\",\"ru\":\"В субботу я встречаюсь с другом. И в воскресенье тоже.\"},{\"ko\":\"저는 도서관에서 공부해요. 카페에서도 공부해요.\",\"ru\":\"Я занимаюсь в библиотеке. И в кафе тоже.\"}]},{\"type\":\"warning\",\"text\":\"도 не стоит вместе с 은/는 и 이/가: или одно, или другое. А с 에 и 에서 она складывается: 에도, 에서도 (так можно).\"},{\"type\":\"warning\",\"text\":\"Ещё две ошибки. 를 и 도 вместе нельзя, даже у последнего предмета: 불고기를도 좋아해요 (×) → 불고기도 좋아해요 (○). И не теряй 에 или 에서: 도서관도 가요 (×) → 도서관에도 가요 (○).\"},{\"type\":\"heading\",\"text\":\"Сравни: без 도 и с 도\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"저는 가요. / 저도 가요.\",\"ru\":\"Я иду. / Я тоже иду.\"},{\"ko\":\"학교에 가요. / 학교에도 가요.\",\"ru\":\"Иду в школу. / И в школу иду.\"},{\"ko\":\"토요일에 운동해요. / 일요일에도 운동해요.\",\"ru\":\"В субботу занимаюсь. / И в воскресенье.\"}]},{\"type\":\"tip\",\"text\":\"Предложение без «тоже» говорит о теме (는) или называет подлежащее (가), а с 도 мы добавляем: «и ещё это». Сравни: 저는 학생이에요 — Я студент. 에릭 씨도 학생이에요 — Эрик тоже студент.\"}]},\n{\"id\":\"past_my\",\"ko\":\"았어요 / 었어요\",\"ru\":\"прошедшее время\",\"section\":\"Время\",\"lesson\":\"\",\"about\":\"что уже было: ходил(а), ел(а), был(а) кем-то\",\"blocks\":[{\"type\":\"text\",\"text\":\"К основе глагола или прилагательного добавляется 았어요 / 었어요: так говорят о том, что уже произошло («ходил(а)», «ел(а)», «был вкусным»). Время (어제, 일요일에) обычно ставят в начало.\"},{\"type\":\"formula\",\"text\":\"основа + 았어요 / 었어요; 하다 → 했어요; после существительного 이었어요 / 였어요\"},{\"type\":\"rule\",\"text\":\"Последняя гласная основы ㅏ, ㅗ → 았어요: 알다 → 알았어요, 좋다 → 좋았어요. Любая другая гласная → 었어요: 먹다 → 먹었어요, 맛있다 → 맛있었어요. 하다 → 했어요: 공부하다 → 공부했어요, 깨끗하다 → 깨끗했어요. После 어제 / 오늘 частица 에 не ставится.\"},{\"type\":\"pronunciation\",\"text\":\"Если основа без 받침, гласная часто сливается с 았 / 었 и остаётся один слог: 가 + 았 = 갔, 오 + 았 = 왔, 보 + 았 = 봤, 마시 + 었 = 마셨, 배우 + 었 = 배웠, 쓰 + 었 = 썼. Читается 았어요 [아써요], 었어요 [어써요], 였어요 [여써요]: ㅆ здесь 받침.\"},{\"type\":\"table\",\"head\":[\"Слово\",\"Прошедшее\",\"Перевод\",\"Почему\"],\"rows\":[[\"가다\",\"갔어요\",\"ходил(а)\",\"ㅏ → 았, сливается\"],[\"먹다\",\"먹었어요\",\"ел(а)\",\"ㅓ → 었\"],[\"공부하다\",\"공부했어요\",\"учился, училась\",\"하다 → 했어요\"],[\"선생님\",\"선생님이었어요\",\"был(а) учителем\",\"받침 есть → 이었어요\"],[\"기자\",\"기자였어요\",\"был(а) журналистом\",\"받침 нет → 였어요\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"어제 학교에 갔어요.\",\"ru\":\"Вчера ходил(а) в школу.\"},{\"ko\":\"비빔밥이 맛있었어요.\",\"ru\":\"Бибимбап был вкусный.\"},{\"ko\":\"어제 아야나 씨하고 쇼핑했어요?\",\"ru\":\"Вчера ходили по магазинам с Аяной?\"},{\"ko\":\"아니요. 안 했어요.\",\"ru\":\"Нет, не ходил(а).\"},{\"ko\":\"저는 가수였어요.\",\"ru\":\"Я был(а) певцом.\"},{\"ko\":\"어제는 월요일이었어요.\",\"ru\":\"Вчера был понедельник.\"}]},{\"type\":\"warning\",\"text\":\"가았어요 (×), 마시었어요 (×) → 갔어요 (○), 마셨어요 (○). После гласной без 받침 слог чаще всего сливается.\"},{\"type\":\"warning\",\"text\":\"먹았어요 (×), 좋었어요 (×) → 먹었어요 (○), 좋았어요 (○). Смотри на последнюю гласную основы: ㅏ, ㅗ → 았, остальные → 었.\"},{\"type\":\"warning\",\"text\":\"선생님였어요 (×), 기자이었어요 (×) → 선생님이었어요 (○), 기자였어요 (○). После 받침 이었어요, без 받침 였어요.\"},{\"type\":\"warning\",\"text\":\"어제에 갔어요 (×) → 어제 갔어요 (○). После 어제 / 오늘 частица 에 не нужна.\"},{\"type\":\"heading\",\"text\":\"Сравни: было, есть, будет\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"갔어요. / 가요. / 갈 거예요.\",\"ru\":\"Ходил(а). / Иду. / Пойду.\"},{\"ko\":\"먹었어요. / 먹어요. / 먹을 거예요.\",\"ru\":\"Ел(а). / Ем. / Буду есть.\"},{\"ko\":\"학생이었어요. / 학생이에요. / 학생이 아니었어요.\",\"ru\":\"Был(а) учеником. / Я ученик. / Не был(а) учеником.\"}]},{\"type\":\"tip\",\"text\":\"Скажи вслух три предложения о том, что было вчера: что делал(а), куда ходил(а) и что ел(а). Образец: 어제 도서관에서 책을 읽었어요. Дополнительно: задай вопрос 어제 뭐 했어요? и ответь на него.\"}]},\n{\"id\":\"future_my\",\"ko\":\"(으)ㄹ 거예요\",\"ru\":\"планы, будущее\",\"section\":\"Время\",\"lesson\":\"\",\"about\":\"что буду делать: завтра, на выходных\",\"blocks\":[{\"type\":\"text\",\"text\":\"Так говорят о планах и будущем: «буду делать», «собираюсь». Только глаголы. Время (내일, 주말에, 저녁에) обычно ставят в начало предложения.\"},{\"type\":\"formula\",\"text\":\"основа глагола + -(으)ㄹ 거예요\"},{\"type\":\"rule\",\"text\":\"받침 нет → просто ㄹ под последней гласной: 가 + ㄹ = 갈 거예요. 받침 есть → 을 + 거예요: 먹 + 을 = 먹을 거예요. 받침 ㄹ (살다, 만들다) → ничего не добавляем: 살 거예요, 만들 거예요.\"},{\"type\":\"pronunciation\",\"text\":\"Пишется 거예요, а читается [꺼예요]: после ㄹ звук ㄱ становится твёрдым. Выбор между -ㄹ и -을 зависит от 받침 основы (как у 은/는, 이/가, 을/를), а сам 거예요 не меняется никогда.\"},{\"type\":\"table\",\"head\":[\"Глагол\",\"Форма\",\"Перевод\",\"받침\"],\"rows\":[[\"가다\",\"갈 거예요\",\"пойду\",\"нет\"],[\"하다\",\"할 거예요\",\"буду делать\",\"нет\"],[\"쉬다\",\"쉴 거예요\",\"буду отдыхать\",\"нет\"],[\"배우다\",\"배울 거예요\",\"буду учиться\",\"нет\"],[\"마시다\",\"마실 거예요\",\"буду пить\",\"нет\"],[\"가르치다\",\"가르칠 거예요\",\"буду преподавать\",\"нет\"],[\"운전하다\",\"운전할 거예요\",\"буду водить машину\",\"нет\"],[\"청소하다\",\"청소할 거예요\",\"буду убирать\",\"нет\"],[\"먹다\",\"먹을 거예요\",\"буду есть\",\"есть\"],[\"읽다\",\"읽을 거예요\",\"буду читать\",\"есть\"],[\"찍다\",\"찍을 거예요\",\"буду снимать (фото)\",\"есть\"],[\"살다\",\"살 거예요\",\"буду жить\",\"ㄹ\"],[\"만들다\",\"만들 거예요\",\"буду делать, готовить\",\"ㄹ\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"저녁에 한국어 책을 읽을 거예요.\",\"ru\":\"Вечером буду читать книгу по-корейски.\"},{\"ko\":\"토요일에 운동할 거예요.\",\"ru\":\"В субботу буду заниматься спортом.\"},{\"ko\":\"내일 친구를 만날 거예요.\",\"ru\":\"Завтра встречусь с другом.\"},{\"ko\":\"집에서 쉴 거예요.\",\"ru\":\"Буду отдыхать дома.\"},{\"ko\":\"주말에 뭐 할 거예요?\",\"ru\":\"Что будете делать на выходных?\"},{\"ko\":\"오늘 저녁에 고기를 안 먹을 거예요.\",\"ru\":\"Сегодня вечером не буду есть мясо.\"},{\"ko\":\"혼자 영화를 볼 거예요.\",\"ru\":\"Буду смотреть фильм одна/один.\"},{\"ko\":\"바다에 갈 거예요.\",\"ru\":\"Поеду на море.\"},{\"ko\":\"사진을 찍을 거예요.\",\"ru\":\"Буду фотографировать.\"},{\"ko\":\"서울에서 살 거예요.\",\"ru\":\"Буду жить в Сеуле.\"}]},{\"type\":\"warning\",\"text\":\"먹ㄹ 거예요 (×), 가을 거예요 (×) → 먹을 거예요 (○), 갈 거예요 (○). После 받침 нужно 을, без 받침 только ㄹ.\"},{\"type\":\"warning\",\"text\":\"내일에 갈 거예요 (×) → 내일 갈 거예요 (○). После 오늘 / 내일 / 지금 / 언제 частица 에 не ставится; при двух словах времени 에 один раз в конце: 토요일 저녁에.\"},{\"type\":\"warning\",\"text\":\"갈 안 거예요 (×) → 안 갈 거예요 (○). 안 стоит перед глаголом; у глаголов на 하다: 운동 안 할 거예요 (○).\"},{\"type\":\"heading\",\"text\":\"Сравни: сейчас и план\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"가요. / 갈 거예요.\",\"ru\":\"Иду, хожу. / Пойду, собираюсь пойти.\"},{\"ko\":\"지금 공부해요. / 내일 공부할 거예요.\",\"ru\":\"Сейчас учусь. / Завтра буду учиться.\"},{\"ko\":\"안 가요. / 안 갈 거예요.\",\"ru\":\"Не иду. / Не пойду.\"}]},{\"type\":\"tip\",\"text\":\"Вопрос о планах: 주말에 뭐 할 거예요? Ответ: 바다에 갈 거예요. — 바다에서 뭐 할 거예요? — 사진을 찍을 거예요. Скажи вслух три предложения о том, что будешь делать завтра, в субботу и в воскресенье.\"}]},\n{\"id\":\"man\",\"ko\":\"만 (только)\",\"ru\":\"«только» — выделяет одно\",\"section\":\"Частицы\",\"lesson\":\"\",\"about\":\"«только я», «только дома»\",\"blocks\":[{\"type\":\"text\",\"text\":\"Частица 만 ставится после существительного и значит «только, лишь»: выделяет одно и исключает остальное.\"},{\"type\":\"formula\",\"text\":\"[слово] + 만\"},{\"type\":\"rule\",\"text\":\"도 = «тоже» (добавляет), 만 = «только» (исключает). 받침 на 만 не влияет: после гласной и после согласной всегда просто 만. А вот с 은/는, 이/가 и 을/를 она не ставится вместе: 만 их заменяет.\"},{\"type\":\"table\",\"head\":[\"Что без «только»\",\"Что ставим\",\"Пример\"],\"rows\":[[\"친구 (받침 нет)\",\"친구만\",\"친구만 와요. — Приходит только друг.\"],[\"선생님 (받침 есть)\",\"선생님만\",\"교실에 선생님만 있어요. — В классе только учитель.\"],[\"학교에 (куда)\",\"학교에만\",\"학교에만 가요. — Хожу только в школу.\"],[\"집에서 (где)\",\"집에서만\",\"집에서만 커피를 마셔요. — Кофе пью только дома.\"],[\"일요일에 (когда)\",\"일요일에만\",\"일요일에만 청소해요. — Убираюсь только по воскресеньям.\"]]},{\"type\":\"examples\",\"examples\":[{\"ko\":\"저는 이 가수만 좋아해요.\",\"ru\":\"Мне нравится только этот певец.\"},{\"ko\":\"우리 반에서 저만 영국 사람이에요.\",\"ru\":\"В нашей группе только я англичанин.\"},{\"ko\":\"교실에 선생님만 있어요.\",\"ru\":\"В классе только учитель.\"},{\"ko\":\"저는 김치만 먹어요.\",\"ru\":\"Я ем только кимчхи.\"},{\"ko\":\"일요일에만 청소해요.\",\"ru\":\"Убираюсь только по воскресеньям.\"},{\"ko\":\"집에서만 커피를 마셔요.\",\"ru\":\"Пью кофе только дома.\"},{\"ko\":\"하이 씨만 회사원이에요.\",\"ru\":\"Только Хай сотрудник компании.\"},{\"ko\":\"평일에만 학교에 가요.\",\"ru\":\"В школу хожу только в будни.\"},{\"ko\":\"돌하르방은 제주도에만 있어요.\",\"ru\":\"Статуи дольхарбан есть только на острове Чеджу.\"}]},{\"type\":\"warning\",\"text\":\"저는만 있어요 (×) → 저만 있어요 (○). Рядом с 만 не нужны 은/는 и 이/가.\"},{\"type\":\"warning\",\"text\":\"책을만 읽어요 (×) → 책만 읽어요 (○). Вместо 을/를 тоже ставим просто 만.\"},{\"type\":\"warning\",\"text\":\"학교만에 가요 (×) → 학교에만 가요 (○). Порядок такой: сначала 에 / 에서, потом 만.\"},{\"type\":\"heading\",\"text\":\"Сравни: 도 и 만\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"저도 가요. / 저만 가요.\",\"ru\":\"Я тоже иду. / Иду только я.\"},{\"ko\":\"친구가 안 왔어요. / 친구만 안 왔어요.\",\"ru\":\"Друг не пришёл. / Не пришёл только друг (остальные пришли).\"}]},{\"type\":\"tip\",\"text\":\"Не путай: 김치만 — «только кимчхи», а 만 원 — «десять тысяч вон»: там 만 это число, оно пишется отдельным словом. Скажи вслух три предложения о себе с 만: что ешь только дома, куда ходишь только по выходным, что любишь только ты.\"}]},\n{\"id\":\"thanks\",\"ko\":\"감사합니다\",\"ru\":\"уровни вежливости «спасибо»\",\"section\":\"Вежливость\",\"lesson\":\"\",\"about\":\"от 고마워 до 진심으로 감사합니다\",\"blocks\":[{\"type\":\"text\",\"text\":\"Выбор формы зависит от того, кому говоришь — от самого неформального до самого торжественного.\"},{\"type\":\"table\",\"head\":[\"Уровень\",\"Форма\",\"Чтение\",\"Кому\"],\"rows\":[[\"1\",\"고마워\",\"комаво\",\"друзьям (самое неформальное)\"],[\"2\",\"고마워요\",\"комавоё\",\"знакомым / близким старше тебя\"],[\"3\",\"감사해요\",\"камсахэё\",\"коллегам, товарищам\"],[\"4\",\"감사합니다\",\"камсахамнида\",\"по работе / бизнесу, начальнику\"],[\"5\",\"정말 감사합니다\",\"чонгмаль камсахамнида\",\"огромное спасибо\"],[\"6\",\"진심으로 감사합니다\",\"чинсимыро камсахамнида\",\"искренне благодарю (самое формальное)\"]]}]},\n{\"id\":\"yeon\",\"ko\":\"연음\",\"ru\":\"связывание звуков\",\"section\":\"Произношение\",\"lesson\":\"\",\"about\":\"받침 переезжает в следующий слог\",\"blocks\":[{\"type\":\"text\",\"text\":\"Слог заканчивается на согласную (받침), а следующий слог начинается с пустой ㅇ (как в 이에요, 은/는, 이 и т.д.). Тогда согласная из 받침 «переезжает» в начало следующего слога.\"},{\"type\":\"table\",\"head\":[\"Написано\",\"Как звучит на самом деле\",\"По буквам\"],\"rows\":[[\"이것은\",\"и-го-сын\",\"и-гот-ын\"],[\"저것은\",\"чо-го-сын\",\"чо-гот-ын\"],[\"책이에요\",\"че-ги-е-ё\",\"чек-ие-ё\"],[\"먹어요\",\"мо-го-ё\",\"мок-оё\"],[\"앞에\",\"а-пе\",\"ап-е\"]]}]},\n{\"id\":\"pyeong\",\"ko\":\"평음\",\"ru\":\"озвончение ㄱ ㄷ ㅂ ㅈ\",\"section\":\"Произношение\",\"lesson\":\"\",\"about\":\"в начале слова глухо, дальше звонко\",\"blocks\":[{\"type\":\"text\",\"text\":\"Простые согласные ㄱ ㄷ ㅂ ㅈ (к/г, т/д, п/б, ч/дж) звучат глухо только в самом начале слова или фразы. Если та же буква оказывается не в начале (между гласными или после ㄴ/ㅁ/ㄹ), она автоматически озвончается. Одно правило для всех четырёх букв.\"},{\"type\":\"table\",\"head\":[\"Написано\",\"Звучит\"],\"rows\":[[\"가가가\",\"ка-га-га\"],[\"다다다\",\"та-да-да\"],[\"바바바\",\"па-ба-ба\"],[\"자자자\",\"ча-джа-джа\"]]}]},\n{\"id\":\"counters\",\"ko\":\"개 / 병 / 잔 / 그릇\",\"ru\":\"счётные слова: штука, бутылка, чашка, миска\",\"section\":\"Числительные\",\"lesson\":\"\",\"about\":\"«два кофе», «одна кола»\",\"blocks\":[{\"type\":\"text\",\"text\":\"Когда считаешь предметы, после числа ставят счётное слово. Какое именно, зависит от того, что считаешь.\"},{\"type\":\"formula\",\"text\":\"[предмет] + [число] + [счётное слово]\"},{\"type\":\"table\",\"head\":[\"Слово\",\"Что считаем\",\"Пример\"],\"rows\":[[\"개\",\"штуки, любые мелкие предметы\",\"볼펜 세 개 — три ручки\"],[\"병\",\"бутылки\",\"콜라 한 병 — бутылка колы\"],[\"잔\",\"чашки, стаканы (напиток)\",\"커피 두 잔 — две чашки кофе\"],[\"그릇\",\"миски, порции еды\",\"비빔밥 세 그릇 — три порции бибимбапа\"]]},{\"type\":\"rule\",\"text\":\"Порядок: сначала предмет, потом число (в форме для счёта: 한, 두, 세, 네…), потом счётное слово. Частица обычно не нужна: 커피 두 잔 주세요.\"},{\"type\":\"examples\",\"examples\":[{\"ko\":\"콜라 한 병 주세요.\",\"ru\":\"Дайте, пожалуйста, бутылку колы.\"},{\"ko\":\"커피 두 잔 주세요.\",\"ru\":\"Дайте, пожалуйста, две чашки кофе.\"},{\"ko\":\"비빔밥 세 그릇 주세요.\",\"ru\":\"Дайте, пожалуйста, три порции бибимбапа.\"},{\"ko\":\"볼펜이 몇 개 있어요?\",\"ru\":\"Сколько ручек есть?\"},{\"ko\":\"세 개 있어요.\",\"ru\":\"Есть три.\"}]},{\"type\":\"tip\",\"text\":\"Если из разговора понятно, что считают, предмет можно опустить: «Сколько есть? — Три» = 세 개 있어요.\"},{\"type\":\"warning\",\"text\":\"Число перед счётным словом берётся корейское (한, 두, 세…), а не китайское: 한 병 (○), 일 병 (×).\"}]},\n{\"id\":\"assim\",\"ko\":\"동화\",\"ru\":\"ассимиляция согласных (как «ㄱ + ㄴ» звучит иначе)\",\"section\":\"Произношение\",\"lesson\":\"\",\"about\":\"막내 → [망내], 입니다 → [임니다]\",\"blocks\":[{\"type\":\"text\",\"text\":\"Когда 받침 (согласная в конце слога) встречается с началом следующего слога (ㄴ, ㅁ, ㄹ), они подстраиваются друг под друга, и звучание отличается от написания.\"},{\"type\":\"table\",\"head\":[\"Что стоит\",\"Как звучит\",\"Пример\"],\"rows\":[[\"ㄱ + ㄴ\",\"ㅇ + ㄴ\",\"막내 → [망내]\"],[\"ㄱ + ㄹ\",\"ㅇ + ㄴ\",\"국립 → [궁닙]\"],[\"ㄱ + ㅁ\",\"ㅇ + ㅁ\",\"박물관 → [방물관]\"],[\"ㄷ + ㄴ\",\"ㄴ + ㄴ\",\"끝나다 → [끈나다]\"],[\"ㄷ + ㅁ\",\"ㄴ + ㅁ\",\"몇 명 → [면명]\"],[\"ㅂ + ㄴ\",\"ㅁ + ㄴ\",\"입니다 → [임니다]\"],[\"ㅂ + ㄹ\",\"ㅁ + ㄴ\",\"컵라면 → [컴나면]\"],[\"ㅂ + ㅁ\",\"ㅁ + ㅁ\",\"입맛 → [임맏]\"],[\"ㄴ + ㄹ\",\"ㄹ + ㄹ\",\"한류 → [할류]\"],[\"ㄹ + ㄴ\",\"ㄹ + ㄹ\",\"설날 → [설랄]\"],[\"ㅁ + ㄹ\",\"ㅁ + ㄴ\",\"음력 → [음녁]\"],[\"ㅇ + ㄹ\",\"ㅇ + ㄴ\",\"능력 → [능녁]\"]]},{\"type\":\"tip\",\"text\":\"Читать так, как слышишь, не обязательно: пиши по правилам, а в речи звук сам подстраивается. Самый частый пример — 입니다: пишется «imnida» через ㅂ, но звучит [임니다].\"}]},\n{\"id\":\"rieul\",\"ko\":\"ㄹ\",\"ru\":\"два звучания буквы ㄹ\",\"section\":\"Произношение\",\"lesson\":\"\",\"about\":\"[р] в начале слога, [ль] в конце\",\"blocks\":[{\"type\":\"text\",\"text\":\"Буква ㄹ звучит по-разному в зависимости от места в слове.\"},{\"type\":\"table\",\"head\":[\"Где\",\"Как звучит\",\"Пример\"],\"rows\":[[\"В начале слога (перед гласной)\",\"[р] — лёгкий, короткий\",\"라 [ра], 로 [ро]\"],[\"В конце слога\",\"[ль]\",\"말, 서울\"],[\"Две ㄹ подряд\",\"[лл] — одно длинное «ль»\",\"빨리\"]]},{\"type\":\"rule\",\"text\":\"ㄹ = [р], если за ней идёт гласная, и ㄹ = [ль], если это 받침 (конец слога).\"},{\"type\":\"tip\",\"text\":\"Фонетика взята из заметок Леры. Для чтения справочник «Хангыль» не менялся.\"}]}\n]}\n"

